#!/usr/bin/env node
/**
 * arch-atlas replacement for Understand-Anything's generate-ignore.mjs.
 *
 * The original delegates to `generateStarterIgnoreFile` in
 * `@understand-anything/core` — reads .gitignore, deduplicates against
 * built-in defaults, emits language-grouped test-file suggestions. Not
 * vendored for the same reason as compute-batches.mjs (research.md D4):
 * that package isn't published to npm.
 *
 * This version writes a fixed exclusion list — the same secret/build-output
 * patterns already enforced at the tool-permission layer per FR-015
 * (src/analysis/resource-loader.ts), plus common non-source directories.
 * No .gitignore-awareness, no per-language test-file heuristics.
 *
 * Usage: node generate-ignore.mjs <projectRoot>
 */
import { existsSync, mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const FIXED_EXCLUSIONS = [
  '# Generated by arch-atlas (plain, fixed list — see generate-ignore.mjs header)',
  'node_modules/',
  '.git/',
  'dist/',
  'build/',
  'coverage/',
  '__pycache__/',
  '.venv/',
  'venv/',
  '.env',
  '.env.*',
  '*.key',
  '*.pem',
  '*.p12',
  '*.pfx',
  '*secret*',
  '*credential*',
  '*password*',
].join('\n');

function resolveUaDir(projectRoot) {
  return join(projectRoot, '.ua');
}

function main() {
  const projectRoot = process.argv[2];
  if (!projectRoot) {
    console.error('Usage: generate-ignore.mjs <projectRoot>');
    process.exit(1);
  }
  const uaDir = resolveUaDir(projectRoot);
  if (!existsSync(uaDir)) mkdirSync(uaDir, { recursive: true });
  writeFileSync(join(uaDir, '.understandignore'), FIXED_EXCLUSIONS + '\n', 'utf8');
  console.error(`Wrote fixed exclusion list to ${join(uaDir, '.understandignore')}`);
}

main();
